INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Optimierung einer Datenbank immer hardwareabhängig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Software-Tuning hilft"}, {"text": "Ja", "correct": false, "because": "Nicht nur Hardware zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Optimierung einer Datenbank?', 3, '[{"text": "Abfragegeschwindigkeit", "correct": true, "because": "Verbessert Nutzererfahrung"}, {"text": "Speicherplatz", "correct": false, "because": "Sekundär zur Leistung"}, {"text": "Einfache Installation", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen verbessern die Leistung?', 5, '[{"text": "Indexierung", "correct": true, "because": "Schnellere Suchen"}, {"text": "Abfragen optimieren", "correct": true, "because": "Reduziert Ressourcenverbrauch"}, {"text": "Mehr RAM", "correct": false, "because": "Hardwarelösung"}, {"text": "Bunte Logs", "correct": false, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Optimierung reduziert Ladezeiten. b) Sie erfordert immer Neustarts.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Neustarts nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Leistungssteigerung?', 4, '[{"text": "Abfragepläne", "correct": false, "because": "Wichtig für Effizienz"}, {"text": "Indexwartung", "correct": false, "because": "Sichert Performance"}, {"text": "GUI-Design", "correct": true, "because": "Kein Einfluss auf Leistung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Optimierung auch Speicherplatz spart?', 2, '[{"text": "Ja", "correct": true, "because": "Durch Komprimierung möglich"}, {"text": "Nein", "correct": false, "because": "Neben Leistung auch Platz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wähle ich für schnellere Abfragen?', 3, '[{"text": "Index erstellen", "correct": true, "because": "Verkürzt Suchzeiten"}, {"text": "Daten verdoppeln", "correct": false, "because": "Verschlechtert Leistung"}, {"text": "Logs deaktivieren", "correct": false, "because": "Nur Diagnose beeinflusst"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt mir eine optimierte Datenbank?', 5, '[{"text": "Schnellere Antwortzeiten", "correct": true, "because": "Effizientere Abfragen"}, {"text": "Geringerer Ressourcenverbrauch", "correct": true, "because": "Weniger Last"}, {"text": "Bessere Grafik", "correct": false, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Optimierung verbessert Skalierung. b) Sie ist einmalig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kontinuierlich nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Optimierung?', 4, '[{"text": "Abfrageanalyse", "correct": false, "because": "Zeigt Schwachstellen"}, {"text": "Indexstrategie", "correct": false, "because": "Steigert Effizienz"}, {"text": "Spiele-Engine", "correct": true, "because": "Kein Datenbankzweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Optimierung nur für große Datenbanken?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine profitieren"}, {"text": "Ja", "correct": false, "because": "Größe egal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Optimierung effektiv?', 4, '[{"text": "Gezielte Indizes", "correct": true, "because": "Schnellere Zugriffe"}, {"text": "Abfrage-Tuning", "correct": true, "because": "Reduziert Last"}, {"text": "Höhere CPU-Taktung", "correct": false, "because": "Hardwarelösung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Optimierung nur Hardware braucht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Softwaremaßnahmen entscheidend"}, {"text": "Ja", "correct": false, "because": "Nicht nur Hardware"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Optimierung unwichtig?', 3, '[{"text": "Abfragepläne", "correct": false, "because": "Zeigen Engpässe"}, {"text": "Indexwartung", "correct": false, "because": "Hält Leistung"}, {"text": "Farbanpassung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Optimierung braucht Analyse. b) Sie funktioniert ohne Wartung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wartung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Optionen verbessern die Datenbankleistung?', 5, '[{"text": "Indexierung", "correct": true, "because": "Schnellere Suchen"}, {"text": "Partitionierung", "correct": true, "because": "Teilt Daten effizient"}, {"text": "Mehr Festplatten", "correct": false, "because": "Hardwarelösung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für bessere Skalierung?', 4, '[{"text": "Tabellenpartitionierung", "correct": true, "because": "Verteilt Datenlast"}, {"text": "Daten duplizieren", "correct": false, "because": "Erhöht Speicherbedarf"}, {"text": "Logs abschalten", "correct": false, "because": "Beeinträchtigt Diagnose"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Optimierung auch Kosten senken?', 3, '[{"text": "Ja", "correct": true, "because": "Weniger Ressourcenverbrauch"}, {"text": "Nein", "correct": false, "because": "Effizienz spart"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Optimierung auch Sicherheit erhöht?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Leistung"}, {"text": "Ja", "correct": false, "because": "Sicherheit separat"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft mir bei der Optimierung?', 4, '[{"text": "EXPLAIN PLAN", "correct": true, "because": "Zeigt Abfrageausführung"}, {"text": "Texteditor", "correct": false, "because": "Kein Analysewerkzeug"}, {"text": "Browser", "correct": false, "because": "Nicht datenbankspezifisch"}]');
